/**
 * Client-side runtime error capture.
 *
 * Registers global handlers to catch and report:
 *  - Unhandled promise rejections
 *  - Uncaught exceptions (window.onerror)
 *  - Console.error intercept (optional)
 *
 * Call `initRuntimeErrorCapture()` once at the app entry point.
 */

interface ErrorReport {
  type: "unhandledrejection" | "onerror" | "console-error";
  message: string;
  stack?: string;
  url: string;
  userAgent: string;
  timestamp: string;
  extra?: Record<string, unknown>;
}

const REPORTS: ErrorReport[] = [];
const MAX_STORED = 50;

function storeReport(report: ErrorReport): void {
  REPORTS.push(report);
  if (REPORTS.length > MAX_STORED) REPORTS.shift();

  // Persist to sessionStorage for diagnostic access
  try {
    sessionStorage.setItem("__error_log", JSON.stringify(REPORTS.slice(-20)));
  } catch {
    // sessionStorage may be full
  }
}

async function sendToServer(report: ErrorReport): Promise<void> {
  try {
    await fetch("/api/log", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        ...report,
        level: "error",
      }),
      signal: AbortSignal.timeout(2000),
    });
  } catch {
    // Silently fail — we're already in an error path
  }
}

/**
 * Get all captured runtime errors (for diagnostic display).
 */
export function getCapturedErrors(): ErrorReport[] {
  return [...REPORTS];
}

/**
 * Clear captured error log.
 */
export function clearCapturedErrors(): void {
  REPORTS.length = 0;
  try {
    sessionStorage.removeItem("__error_log");
  } catch {
    // ok
  }
}

/**
 * Initialize runtime error capture.
 * Call once at app entry (e.g., in a Provider or layout).
 */
export function initRuntimeErrorCapture(options?: {
  /** Also intercept console.error calls (default: false) */
  interceptConsole?: boolean;
  /** Report errors to server (default: true) */
  reportToServer?: boolean;
}): () => void {
  const reportToServer = options?.reportToServer !== false;
  const interceptConsole = options?.interceptConsole === true;

  const url = typeof window !== "undefined" ? window.location.href : "";
  const userAgent = typeof navigator !== "undefined" ? navigator.userAgent : "";
  const ts = () => new Date().toISOString();
  const makeReport = (type: ErrorReport["type"], message: string, stack?: string, extra?: Record<string, unknown>): ErrorReport => ({
    type,
    message,
    stack,
    url,
    userAgent,
    timestamp: ts(),
    extra,
  });

  // 1. Unhandled promise rejections
  const rejectionHandler = (event: PromiseRejectionEvent): void => {
    const message = event.reason?.message || String(event.reason);
    const stack = event.reason?.stack || "";
    const report = makeReport("unhandledrejection", message, stack, {
      reasonType: typeof event.reason,
    });
    storeReport(report);
    if (reportToServer) sendToServer(report);
  };
  window.addEventListener("unhandledrejection", rejectionHandler);

  // 2. Global onerror
  const errorHandler = (event: ErrorEvent): void => {
    const message = event.message || "Unknown error";
    const stack = event.error?.stack || "";
    const report = makeReport("onerror", message, stack, {
      filename: event.filename,
      line: event.lineno,
      col: event.colno,
    });
    storeReport(report);
    if (reportToServer) sendToServer(report);
  };
  window.addEventListener("error", errorHandler);

  // 3. Optional console.error interception
  let restoreConsole: (() => void) | null = null;
  if (interceptConsole) {
    const originalConsoleError = console.error;
    console.error = (...args: unknown[]) => {
      const message = args.map((a) => (typeof a === "string" ? a : String(a))).join(" ");
      const report = makeReport("console-error", message, undefined, {
        args: args.slice(0, 3).map((a) => (typeof a === "string" ? a.slice(0, 200) : typeof a)),
      });
      storeReport(report);
      // Still call the original
      originalConsoleError.apply(console, args);
    };
    restoreConsole = () => {
      console.error = originalConsoleError;
    };
  }

  // Return a cleanup function
  return () => {
    window.removeEventListener("unhandledrejection", rejectionHandler);
    window.removeEventListener("error", errorHandler);
    if (restoreConsole) restoreConsole();
  };
}
