"use client";

import { ReactNode, useEffect } from "react";
import { SessionProvider } from "next-auth/react";
import { initRuntimeErrorCapture } from "@/lib/runtime-errors";

interface ProvidersProps {
  children: ReactNode;
}

/**
 * App-wide client-side providers.
 * Wires in:
 *  - SessionProvider (next-auth — required by admin/compare/history pages)
 *  - Runtime error capture (unhandled rejections, onerror)
 *  - Future providers (theme, etc.) go here
 */
export function Providers({ children }: ProvidersProps) {
  useEffect(() => {
    // Initialize runtime error capture on mount
    const cleanup = initRuntimeErrorCapture({
      interceptConsole: false,
      reportToServer: true,
    });
    return cleanup;
  }, []);

  return <SessionProvider>{children}</SessionProvider>;
}
